INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`) VALUES
(41182, 'ruRU', 'Раскрытие сферы Скиаллакса', 'Встретьтесь с Тэ''теланом Кровавым Стражем у входа в зал, где хранится сфера Скиаллакса. Оказавшись внутри, установите заряды на оболочку и добудьте артефакт.', 'Нам нужно спешить, пока ночнорождённые не поняли, что мы ищем.$b$bЯ беру с собой гоблинов на случай, если нам встретятся препятствия по пути.$b$bЯ отметил на твоей карте вход в зал, где хранится сфера.$b$bВстретимся там, как только будешь готов, и мы заберём этот артефакт себе.'),
(41185, 'ruRU', 'Ключи к успеху', 'Принесите форму Аларду Шмиду в Даларан и попросите его помочь выковать новый набор ключей. Вернитесь к Тэ''телану, когда набор будет готов.', 'Я хочу, чтобы ты отнёс форму кузнецу в Даларане. Кажется, его зовут Алард.$b$bПопроси его помочь выковать новый набор ключей.$b$bЯ нашёл надпись на обратной стороне формы, которая может подсказать, что открывают эти ключи. Я останусь здесь и попробую перевести текст.'),
(41192, 'ruRU', 'Правильный путь', 'Встретьтесь с Лессой в Крутогорье.', 'Эта новая лавка, кажется, неплохо складывается. И всё же осталось так много организовать.$b$b$n, Лесса просила твоего присутствия в Крутогорье. Что-то насчёт лося?$b$bЯ не уверен, о чём она говорит, но как только у тебя будет возможность, пожалуйста, зайди к ней.'),
(41193, 'ruRU', 'Упокоение', 'Найдите $1oa осколков костей Эче''ро и верните их Лессе в Крутогорье. Затем наблюдайте за погребальной церемонией, которую проведёт Лесса.', 'Если я смогла найти осколок кости, казалось бы, в случайном месте, значит, кости Эче''ро разбросаны по всему Крутогорью.$b$bМы должны найти его останки и устроить ему достойные похороны, которых он заслуживает.$b$bОй, прости, если ты не знал — Эче''ро был верховым животным и спутником Хулна Крутогорного.$b$bОн заслуживает почестей, как когда-то их заслужил Хулн.'),
(41201, 'ruRU', 'Шероховатое обнажение лей-камня', '', ''),
